#include "stm32f7xx.h"

void SystemClock_Config(void);
void ADC1_Init(void);
uint32_t ADC1_Read(void);

int main(void) {
  HAL_Init();
  SystemClock_Config();
  ADC1_Init();

  RCC->AHB1ENR |= RCC_AHB1ENR_GPIOIEN;
  GPIOI->MODER |= (1 << (0 * 2));

  while (1) {
    uint32_t val = ADC1_Read();
    if (val > 2048) {
      GPIOI->ODR |= (1 << 0);
    } else {
      GPIOI->ODR &= ~(1 << 0);
    }
    HAL_Delay(100);
  }
}

void ADC1_Init(void) {
  RCC->APB2ENR |= RCC_APB2ENR_ADC1EN;
  RCC->AHB1ENR |= RCC_AHB1ENR_GPIOAEN;
  GPIOA->MODER |= (3 << (0 * 2));
  ADC1->CR2 = 0;
  ADC1->SQR3 = 0;
  ADC1->CR2 |= ADC_CR2_ADON;
}

uint32_t ADC1_Read(void) {
  ADC1->CR2 |= ADC_CR2_SWSTART;
  while (!(ADC1->SR & ADC_SR_EOC));
  return ADC1->DR;
}

